chmod +x run_sob_*.sh

echo ""
echo "=== VERIFY: unit tests ==="
export PYTHONPATH="$PWD/src:${PYTHONPATH:-}"
if python -m pytest tests/ -q --ignore=tests/test_extract_bench.py 2>&1 | tail -5; then
  echo "tests done"
else
  echo "WARNING: tests reported failures -- read the output above before running jobs."
fi

echo ""
echo "=== VERIFY: new stages are wired up ==="
python -c "
import ast, sys
for f in ['scripts/08_attribution_controls.py','scripts/09_selective_regeneration_sob.py']:
    ast.parse(open(f).read()); print('  parses:', f)
from probe_extraction.utils.resume import parse_shard, already_extracted
assert parse_shard('2/4') == (1, 4)
print('  resume helpers import cleanly')
"
python scripts/01_extract.py --help 2>/dev/null | grep -E "resume|shard" || \
  echo "  NOTE: --help needs the model stack; check --resume/--shard inside a job instead."

echo ""
echo "============================================================"
echo "INSTALLED."
echo ""
echo "Already completed on this corpus (do NOT re-run):"
echo "  run_sob_attr_controls_a100.sh   300-doc controls"
echo "  run_sob_1k_extract_a100.sh      994 docs extracted"
echo "  run_sob_1k_analysis_a100.sh     label + attribution + controls + regen"
echo ""
echo "NEXT STEP:"
echo "  sbatch run_sob_1k_final_a100.sh"
echo "    -> re-scores Stage 07 and Stage 09 with fused_decomposed, the"
echo "       strongest variant (+0.0364 over answer-only, p=1.7e-05). The"
echo "       existing result files are kept; new ones get a _final suffix."
echo ""
echo "============================================================"
